$extra_scripts = '
<script>
// Typed text
initTyped(document.getElementById("typed-text"), ["Outsourcing","AI Solutions","Healthcare BPO","Publishing Services","Data Annotation","Digital Marketing","Real Estate BPO"], 80);
// Particle canvas
initParticleCanvas("hero-canvas");
// Contact form
(function(){
  var form = document.getElementById("contactForm");
  if (!form) return;
  form.addEventListener("submit", function(e){
    e.preventDefault();
    var btn = document.getElementById("submitBtn");
    var fb  = document.getElementById("form-feedback");
    btn.innerHTML = \'<i class="fas fa-spinner fa-spin"></i> Sending...\';
    btn.disabled = true;
    var data = new FormData(form);
    fetch("api/contact.php", {method:"POST", body:data})
      .then(function(r){return r.json();})
      .then(function(res){
        if (res.success) {
          form.reset();
          var modal = document.getElementById("contactSuccessModal");
          if (modal && window.bootstrap) new bootstrap.Modal(modal).show();
          else { fb.className="mt-3 alert alert-success"; fb.innerHTML=\'<i class="fas fa-check-circle me-2"></i>\'+res.message; fb.classList.remove("d-none"); }
        } else {
          fb.className="mt-3 alert alert-danger"; fb.textContent=res.message; fb.classList.remove("d-none");
        }
      })
      .catch(function(){ fb.className="mt-3 alert alert-danger"; fb.textContent="Network error. Please try again."; fb.classList.remove("d-none"); })
      .finally(function(){ btn.innerHTML=\'<i class="fas fa-paper-plane"></i> Send Message\'; btn.disabled=false; });
  });
})();
</script>';
require_once __DIR__ . '/includes/footer.php';
